# Actionable query now carries the last v1.9 economics/rank context.
pat=r'    public List<Recommendation> actionableR360Now\(\)\{.*?return out;\}\n\n    public String r360TodayPipeline\(\)\{.*?\}\n'
rep='''    public List<Recommendation> actionableR360Now(){long start=LocalDate.now(IST).atStartOfDay(IST).toInstant().toEpochMilli();ArrayList<Recommendation> out=new ArrayList<>();Set<String> seen=new HashSet<>();Cursor c=getReadableDatabase().rawQuery("SELECT sg.id,sg.symbol,sg.category,sg.score,sg.status,sg.entry,sg.mfe,sg.mae,COALESCE(o.last_expected_net,0),COALESCE(o.last_rank_pct,0) FROM signals sg LEFT JOIN r360_v19_obs o ON o.signal_id=sg.id WHERE sg.action='BUY' AND sg.ts>=? AND sg.category NOT IN ('OWN_MODEL_INTRADAY','SECTOR_MOMENTUM_INTRADAY') AND sg.status IN ('SHADOW_ACTIVE','LIVE_ACTIVE') AND sg.symbol!='' ORDER BY CASE WHEN sg.status='LIVE_ACTIVE' THEN 0 ELSE 1 END,sg.score DESC,sg.last_update DESC",new String[]{String.valueOf(start)});try{while(c.moveToNext()&&out.size()<3){String sym=c.getString(1);if(!seen.add(sym))continue;Recommendation r=new Recommendation();r.id=c.getLong(0);r.symbol=sym;r.category=c.getString(2);r.score=c.getDouble(3);r.status=c.getString(4);r.entry=c.getDouble(5);r.mfe=c.getDouble(6);r.mae=c.getDouble(7);r.expectedNet=c.getDouble(8);r.rankPct=c.getDouble(9);out.add(r);}}finally{c.close();}return out;}\n\n    public String r360TodayPipeline(){long start=LocalDate.now(IST).atStartOfDay(IST).toInstant().toEpochMilli();Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(CASE WHEN o.analyses>0 THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN o.data_failures>0 THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN sg.status IN ('NEW','WATCH') THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN sg.status IN ('REJECTED','EXPIRED') THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN sg.status IN ('SHADOW_ACTIVE','LIVE_ACTIVE') THEN 1 ELSE 0 END),0) FROM signals sg LEFT JOIN r360_v19_obs o ON o.signal_id=sg.id WHERE sg.action='BUY' AND sg.ts>=? AND sg.category NOT IN ('OWN_MODEL_INTRADAY','SECTOR_MOMENTUM_INTRADAY')",new String[]{String.valueOf(start)});try{if(c.moveToFirst())return String.format(Locale.US,"TODAY: %d calls • %d live-analysed • %d data issues • %d monitoring • %d expired/rejected • %d ACTIONABLE",c.getLong(0),c.getLong(1),c.getLong(2),c.getLong(3),c.getLong(4),c.getLong(5));}finally{c.close();}return "TODAY: waiting for Research360 calls";}\n'''
s2,n=re.subn(pat,rep,s,count=1,flags=re.S)
if n!=1: raise SystemExit('Db actionable/pipeline replacement failed')
