# v1.9 candidate ledger helpers.
marker='    public Signal getSignal(long id){'
insert='''    public void recordV19Observation(Signal s,MarketSnapshot q,double score,double expectedNet,double rankPct){\n        if(s==null||q==null)return;SQLiteDatabase db=getWritableDatabase();long now=System.currentTimeMillis();double ref=s.entry>0?s.entry:(s.firstLtp>0?s.firstLtp:q.ltp);double pct=(ref>0&&q.ltp>0)?(q.ltp/ref-1)*100.0:0;ContentValues init=new ContentValues();init.put("signal_id",s.id);init.put("strategy_version","1.9");init.put("first_ts",now);init.put("last_ts",now);init.put("initial_ltp",q.ltp);init.put("last_ltp",q.ltp);init.put("max_mfe",Math.max(0,pct));init.put("min_mae",Math.min(0,pct));init.put("max_score",score);init.put("last_expected_net",expectedNet);init.put("max_expected_net",expectedNet);init.put("last_rank_pct",rankPct);init.put("analyses",1);init.put("final_status","MONITORING");long x=db.insertWithOnConflict("r360_v19_obs",null,init,SQLiteDatabase.CONFLICT_IGNORE);if(x==-1){db.execSQL("UPDATE r360_v19_obs SET last_ts=?,last_ltp=?,max_mfe=MAX(max_mfe,?),min_mae=MIN(min_mae,?),max_score=MAX(max_score,?),last_expected_net=?,max_expected_net=MAX(max_expected_net,?),last_rank_pct=?,analyses=analyses+1 WHERE signal_id=?",new Object[]{now,q.ltp,pct,pct,score,expectedNet,expectedNet,rankPct,s.id});}\n    }\n\n    public void recordV19DataFailure(long signalId,String reason){SQLiteDatabase db=getWritableDatabase();long now=System.currentTimeMillis();ContentValues init=new ContentValues();init.put("signal_id",signalId);init.put("strategy_version","1.9");init.put("first_ts",now);init.put("last_ts",now);init.put("data_failures",1);init.put("decision_reason",reason==null?"DATA_UNAVAILABLE":reason);db.insertWithOnConflict("r360_v19_obs",null,init,SQLiteDatabase.CONFLICT_IGNORE);db.execSQL("UPDATE r360_v19_obs SET last_ts=?,data_failures=data_failures+1,decision_reason=? WHERE signal_id=?",new Object[]{now,reason==null?"DATA_UNAVAILABLE":reason,signalId});}\n\n    public void markV19Decision(long signalId,String status,String reason){ContentValues v=new ContentValues();v.put("final_status",status==null?"MONITORING":status);v.put("decision_reason",reason==null?"":reason);v.put("last_ts",System.currentTimeMillis());if("QUALIFIED".equals(status))v.put("qualified_ts",System.currentTimeMillis());getWritableDatabase().update("r360_v19_obs",v,"signal_id=?",new String[]{String.valueOf(signalId)});}\n\n    public void finalizeV19Observation(long signalId,String status){ContentValues v=new ContentValues();v.put("final_status",status==null?"EXPIRED":status);v.put("last_ts",System.currentTimeMillis());getWritableDatabase().update("r360_v19_obs",v,"signal_id=?",new String[]{String.valueOf(signalId)});}\n\n    public double relativePercentileToday(long signalId){long start=LocalDate.now(IST).atStartOfDay(IST).toInstant().toEpochMilli();Cursor x=getReadableDatabase().rawQuery("SELECT score FROM signals WHERE id=?",new String[]{String.valueOf(signalId)});double sc=0;try{if(x.moveToFirst())sc=x.getDouble(0);}finally{x.close();}if(sc<=0)return .5;Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(CASE WHEN score<=? THEN 1 ELSE 0 END),0) FROM signals WHERE action='BUY' AND ts>=? AND category NOT IN ('OWN_MODEL_INTRADAY','SECTOR_MOMENTUM_INTRADAY') AND score>0",new String[]{String.valueOf(sc),String.valueOf(start)});try{if(c.moveToFirst()&&c.getLong(0)>0)return Math.max(0,Math.min(1,(double)c.getLong(1)/c.getLong(0)));}finally{c.close();}return .5;}\n\n    public long v19AnalysedToday(){long start=LocalDate.now(IST).atStartOfDay(IST).toInstant().toEpochMilli();return scalarLong(getReadableDatabase(),"SELECT COUNT(*) FROM r360_v19_obs o JOIN signals s ON s.id=o.signal_id WHERE s.ts>="+start+" AND o.analyses>0");}\n\n'''
if marker not in s: raise SystemExit('Db signal marker missing')
