replacement='''s.liveNetToday=scalarDouble(db,"SELECT COALESCE(SUM(net_pnl),0) FROM trades WHERE mode='LIVE' AND status='CLOSED' AND exit_ts>="+day);s.v19Observed=scalarLong(db,"SELECT COUNT(*) FROM r360_v19_obs WHERE strategy_version='1.9' AND analyses>0");s.v19Qualified=scalarLong(db,"SELECT COUNT(*) FROM r360_v19_obs WHERE strategy_version='1.9' AND qualified_ts>0");s.v19ShadowTrades=scalarLong(db,"SELECT COUNT(*) FROM trades t JOIN r360_v19_obs o ON o.signal_id=t.signal_id WHERE o.strategy_version='1.9' AND t.mode='SHADOW' AND t.status='CLOSED'");s.v19ShadowWins=scalarLong(db,"SELECT COUNT(*) FROM trades t JOIN r360_v19_obs o ON o.signal_id=t.signal_id WHERE o.strategy_version='1.9' AND t.mode='SHADOW' AND t.status='CLOSED' AND t.net_pnl>=100");s.v19ShadowNet=scalarDouble(db,"SELECT COALESCE(SUM(t.net_pnl),0) FROM trades t JOIN r360_v19_obs o ON o.signal_id=t.signal_id WHERE o.strategy_version='1.9' AND t.mode='SHADOW' AND t.status='CLOSED'");return s;}'''
