pat=r'    public static final class Stats\{.*?\n    \}\n    public static final class Signal'
rep='''    public static final class Stats{\n        public long rawCallbacks,notifications,parsed,resolvedSignals,r360ShadowTrades,r360ShadowWins,ownShadowTrades,ownShadowWins,sectorShadowTrades,sectorShadowWins,v19Observed,v19Qualified,v19ShadowTrades,v19ShadowWins;public double r360ShadowNet,ownShadowNet,sectorShadowNet,liveNetToday,v19ShadowNet;\n        public double r360WinRate(){return rate(v19ShadowTrades,v19ShadowWins);}public double historicalR360WinRate(){return rate(r360ShadowTrades,r360ShadowWins);}public double ownWinRate(){return rate(ownShadowTrades,ownShadowWins);}public double sectorWinRate(){return rate(sectorShadowTrades,sectorShadowWins);}\n        public int r360Confidence(){return confidence(v19ShadowTrades,v19ShadowWins,v19ShadowNet,v19Observed,20);}public int ownConfidence(){return confidence(ownShadowTrades,ownShadowWins,ownShadowNet,ownShadowTrades,12);}public int sectorConfidence(){return confidence(sectorShadowTrades,sectorShadowWins,sectorShadowNet,sectorShadowTrades,12);}\n        public int r360Maturity(){return maturity(v19ShadowTrades,50);}public int ownMaturity(){return maturity(ownShadowTrades,18);}public int sectorMaturity(){return maturity(sectorShadowTrades,18);}\n        public boolean r360GateReady(){return r360Confidence()>=80&&v19ShadowTrades>=50&&v19ShadowNet>0&&r360WinRate()>=.60;}public boolean ownGateReady(){return false;}public boolean sectorGateReady(){return false;}public boolean anyLiveGateReady(){return r360GateReady();}\n        private static double rate(long t,long w){return t==0?0:(double)w/t;}private static int maturity(long n,int target){return (int)Math.round(100*(1-Math.exp(-Math.max(0,n)/(double)Math.max(1,target))));}\n        private static int confidence(long trades,long wins,double net,long evidence,int minGate){if(trades<=0)return 0;double wr=(wins+1.0)/(trades+2.0),avg=net/Math.max(1,trades),m=1.0-Math.exp(-(trades+Math.min(evidence,100)*.06)/10.0),quality=clamp((wr-.35)/.45,0,1),netQ=clamp((avg+90)/260.0,0,1);int c=(int)Math.round(100*(.35*m+.45*quality+.20*netQ));if(trades<4)c=Math.min(c,35);else if(trades<8)c=Math.min(c,55);if(trades<minGate)c=Math.min(c,79);return Math.max(0,Math.min(96,c));}\n        private static double clamp(double x,double a,double b){return Math.max(a,Math.min(b,x));}\n    }\n    public static final class Signal'''
s2,n=re.subn(pat,rep,s,count=1,flags=re.S)
