marker='    public double requiredNet100MovePct(double entry,int qty,String product){'
insert='''    public double expectedCapturePct(Db.Signal s,Db.MarketSnapshot q,double score){\n        double x=.30+Math.max(0,score-58)*.022;if("QUANT_INTRADAY".equals(s.category))x+=.08;if(q.depthImbalance>0)x+=Math.min(.20,q.depthImbalance*.30);if(q.dayChangePct>=.15&&q.dayChangePct<=2.5)x+=.10;if(q.rangePosition>=.40&&q.rangePosition<=.88)x+=.08;if(q.rangePosition>.94)x-=.12;if(q.averagePrice>0&&q.ltp>0){double ext=(q.ltp/q.averagePrice-1)*100;if(ext>1.8)x-=.18;}return clamp(x,.20,1.85);\n    }\n\n    public double expectedNet(Db.Signal s,Db.MarketSnapshot q,double score,int qty){if(q==null||q.ltp<=0||qty<=0)return 0;double pct=expectedCapturePct(s,q,score);return netPnl(q.ltp,q.ltp*(1+pct/100.0),qty,product(s));}\n\n    public Qualification qualify(Db.Signal s,Db.MarketSnapshot q,double score,double rankPct,int qty){\n        Qualification z=new Qualification();z.score=score;z.rankPct=rankPct;if(q==null||q.ltp<=0){z.reason="live price unavailable";z.hardVeto=true;return z;}String product=product(s);z.requiredMovePct=requiredNet100MovePct(q.ltp,qty,product);z.expectedCapturePct=expectedCapturePct(s,q,score);z.expectedNet=expectedNet(s,q,score,qty);double threshold=qualifyThreshold(s);if(rankPct>=.85)threshold-=4;else if(rankPct>=.70)threshold-=2;else if(rankPct<=.25)threshold+=1.5;z.threshold=clamp(threshold,67,82);\n        if(qty<=0){z.reason="configured budget cannot buy one share";z.hardVeto=true;return z;}if(q.spreadBps>45){z.reason=String.format(Locale.US,"spread %.1fbps too wide",q.spreadBps);z.hardVeto=true;return z;}if(q.depthImbalance<-.45){z.reason=String.format(Locale.US,"extreme seller depth %.2f",q.depthImbalance);z.hardVeto=true;return z;}if(q.averagePrice>0){double ext=(q.ltp/q.averagePrice-1)*100.0;if(ext>3.5){z.reason=String.format(Locale.US,"severely late %.2f%% above average",ext);z.hardVeto=true;return z;}if(ext<-1.2){z.reason=String.format(Locale.US,"breakdown %.2f%% below average",ext);z.hardVeto=true;return z;}}if(q.dayChangePct>8.0||q.dayChangePct<-3.0){z.reason=String.format(Locale.US,"extreme day move %.2f%%",q.dayChangePct);z.hardVeto=true;return z;}if(q.rangePosition>.985&&q.dayChangePct>3.0){z.reason="vertical chase at day high";z.hardVeto=true;return z;}\n        long age=System.currentTimeMillis()-s.ts;if(!"MOST_OVERNIGHT".equals(s.category)&&age>30L*60L*1000L){z.reason="intraday opportunity stale";z.hardVeto=true;return z;}if(s.entry>0){double d=(q.ltp/s.entry-1)*100.0;if(d<-.60||d>1.00){z.reason=String.format(Locale.US,"waiting for entry window (%.2f%% from R360 entry)",d);return z;}}if(score<z.threshold){z.reason=String.format(Locale.US,"score %.0f below dynamic %.0f",score,z.threshold);return z;}double upsideEnvelope=z.expectedCapturePct*(rankPct>=.85?1.80:1.65);if(z.requiredMovePct>2.75){z.reason=String.format(Locale.US,"₹100 net needs %.2f%%; budget economics too weak",z.requiredMovePct);return z;}if(upsideEnvelope<z.requiredMovePct){z.reason=String.format(Locale.US,"quality good but ₹100-net move %.2f%% exceeds current %.2f%% envelope",z.requiredMovePct,upsideEnvelope);return z;}z.actionable=true;z.reason=String.format(Locale.US,"BUY QUALIFIED • top %.0f%% • expected capture %.2f%% • ₹100 move %.2f%%",rankPct*100,z.expectedCapturePct,z.requiredMovePct);return z;\n    }\n\n    public static final class Qualification{public boolean actionable,hardVeto;public String reason="";public double score,threshold,rankPct,expectedCapturePct,expectedNet,requiredMovePct;}\n\n'''
