old='''        ArrayList<String> syms=new ArrayList<>();for(Db.Signal s:signals)if(!s.symbol.isEmpty()&&!syms.contains(s.symbol))syms.add(s.symbol);Map<String,Double> ltps=groww.getLtps(syms);int fullQuotes=0;\n        for(Db.Signal s:signals){double ltp=ltps.containsKey(s.symbol)?ltps.get(s.symbol):0;if(ltp<=0)continue;updateExcursions(s,ltp);Db.Trade open=db.openTradeForSignal(s.id);if(expireIfNeeded(s,open))continue;boolean near=s.entry<=0||Math.abs((ltp/s.entry-1)*100)<=1.35||open!=null;if(!near){if("NEW".equals(s.status))db.updateSignal(s.id,"WATCH",s.score,s.firstLtp>0?s.firstLtp:ltp,s.mfe,s.mae);continue;}if(fullQuotes>=7&&open==null)continue;Db.MarketSnapshot q=groww.getQuote(s.symbol);fullQuotes++;process(s,q,open);}\n'''
new='''        ArrayList<String> syms=new ArrayList<>();for(Db.Signal s:signals)if(!s.symbol.isEmpty()&&!syms.contains(s.symbol))syms.add(s.symbol);Map<String,Double> ltps=getLtpsResilient(syms);int fullQuotes=0;\n        for(Db.Signal s:signals){Db.Trade open=db.openTradeForSignal(s.id);double ltp=ltps.containsKey(s.symbol)?ltps.get(s.symbol):0;if(ltp>0)updateExcursions(s,ltp);if(expireIfNeeded(s,open))continue;boolean near=s.entry<=0||ltp<=0||Math.abs((ltp/s.entry-1)*100)<=2.50||open!=null;if(!near){if("NEW".equals(s.status))db.updateSignal(s.id,"WATCH",s.score,s.firstLtp>0?s.firstLtp:ltp,s.mfe,s.mae);Db.MarketSnapshot lite=new Db.MarketSnapshot();lite.ltp=ltp;db.recordV19Observation(s,lite,s.score,0,db.relativePercentileToday(s.id));db.markV19Decision(s.id,"MONITORING","outside intensive quote zone");continue;}if(fullQuotes>=9&&open==null)continue;try{Db.MarketSnapshot q=getQuoteResilient(s.symbol);fullQuotes++;if(q==null||q.ltp<=0){db.recordV19DataFailure(s.id,"quote unavailable");continue;}process(s,q,open);}catch(Exception e){db.recordV19DataFailure(s.id,shortMsg(e));}}\n'''
