rep='''    private boolean expireIfNeeded(Db.Signal s,Db.Trade open){LocalTime now=LocalTime.now(IST);boolean intraday=!"MOST_OVERNIGHT".equals(s.category);long age=System.currentTimeMillis()-s.ts;if(open==null&&intraday&&now.isAfter(LocalTime.of(15,16))){db.setSignalStatus(s.id,"EXPIRED");db.finalizeV19Observation(s.id,"EXPIRED_SESSION");return true;}long ttl=intraday?25L*60L*1000L:120L*60L*1000L;if(open==null&&age>ttl){db.setSignalStatus(s.id,"EXPIRED");db.finalizeV19Observation(s.id,"EXPIRED_WINDOW");return true;}return false;}'''
